"""Metric layer.

Token level (paper Sec. 6.1 / R7, authors' eval.py::evaluate_model):
    roc_auc_score(z_test, scores)                       -> AUROC
    auc(*precision_recall_curve(z_test, scores)[1::-1]) -> PR AUC (authors' variant)
    average_precision_score(z_test, scores)             -> sklearn step version (reported too)

Document level (Eq. 3 / R5): aggregate the token scores of each document.
    mean  -> the paper's Eq. (3) aggregation (used as the reported document score)
    max   -> the variant actually used inside the authors' released eval.py
Both are reported so the difference is visible.
"""

import numpy as np
from sklearn.metrics import (roc_auc_score, average_precision_score,
                             precision_recall_curve, auc)


def pr_auc(y_true, scores):
    """Authors' PR AUC: trapezoidal area under the precision-recall curve."""
    precision, recall, _ = precision_recall_curve(y_true, scores)
    return float(auc(recall, precision))


def token_metrics(z_true, scores):
    z = np.asarray(z_true).astype(int)
    s = np.asarray(scores, dtype=float)
    return {
        'n_tokens': int(len(z)),
        'n_positive_tokens': int(z.sum()),
        'token_auroc': float(roc_auc_score(z, s)),
        'token_auprc_authors': pr_auc(z, s),
        'token_auprc_sklearn': float(average_precision_score(z, s)),
    }


def document_scores(scores, lengths, how='mean'):
    """Split the flat token-score vector per document and aggregate (Eq. 3)."""
    s = np.asarray(scores, dtype=float)
    out, start = [], 0
    for L in lengths:
        end = start + int(L)
        chunk = s[start:end]
        if chunk.size == 0:
            out.append(np.nan)
        elif how == 'mean':
            out.append(float(chunk.mean()))
        elif how == 'max':
            out.append(float(chunk.max()))
        else:
            raise ValueError(how)
        start = end
    return np.array(out)


def document_metrics(y_true, scores):
    y = np.asarray(y_true).astype(int)
    s = np.asarray(scores, dtype=float)
    return {
        'n_docs': int(len(y)),
        'n_positive_docs': int(y.sum()),
        'doc_auroc': float(roc_auc_score(y, s)),
        'doc_auprc_authors': pr_auc(y, s),
        'doc_auprc_sklearn': float(average_precision_score(y, s)),
    }

